<?php
declare(strict_types=1);
require_once __DIR__.'/inc/config.php';
require_once __DIR__.'/inc/recap.php';
require_once __DIR__.'/inc/score-odds.php';
require_once __DIR__.'/player-nav.php';
date_default_timezone_set('Europe/London');
$db=new PDO('sqlite:file:'.pc_db_path().'?mode=ro',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
function re($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rf(array $r):string{return '<a href="/fixtures/'.(int)$r['id'].'">'.re($r['home'].' '.$r['actual_home'].'–'.$r['actual_away'].' '.$r['away']).'</a>';}
$period=($_GET['period']??'week')==='month'?'month':'week';
$now=new DateTimeImmutable('now',new DateTimeZone('Europe/London'));$choices=[];
if($period==='month'){
 $month=(string)($_GET['month']??$now->format('Y-m'));
 if(!preg_match('/^20[0-9]{2}-(0[1-9]|1[0-2])$/D',$month)||$month>$now->format('Y-m')){http_response_code(404);exit('Recap not found');}
 $start=new DateTimeImmutable($month.'-01',new DateTimeZone('Europe/London'));$end=$start->modify('+1 month');
 $q=$db->prepare("SELECT id,status,home_score,away_score,kickoff_utc FROM fixtures WHERE julianday(kickoff_utc)>=julianday(?) AND julianday(kickoff_utc)<julianday(?)");
 $q->execute([$start->format('c'),$end->format('c')]);$fixtures=$q->fetchAll(PDO::FETCH_ASSOC);
 $label=$start->format('F Y');$progress=$month===$now->format('Y-m');
 $previous='/recap?period=month&amp;month='.$start->modify('-1 month')->format('Y-m');
 $next=$start->modify('+1 month')->format('Y-m')<=$now->format('Y-m')?'/recap?period=month&amp;month='.$start->modify('+1 month')->format('Y-m'):null;
}else{
 $choices=$db->query("SELECT g.season,g.gameweek,MIN(f.kickoff_utc) first_match FROM fixture_gameweeks g JOIN fixtures f ON f.id=g.fixture_id WHERE EXISTS(SELECT 1 FROM fixture_gameweeks x JOIN fixtures y ON y.id=x.fixture_id WHERE x.season=g.season AND x.gameweek=g.gameweek AND y.status IN ('FT','AET','PEN') AND y.home_score IS NOT NULL AND y.away_score IS NOT NULL AND julianday(y.kickoff_utc)<=julianday('now')) GROUP BY g.season,g.gameweek ORDER BY g.season DESC,g.gameweek DESC")->fetchAll(PDO::FETCH_ASSOC);
 $selected=null;
 foreach($choices as $i=>$c)if(!isset($_GET['week'])||((string)$c['gameweek']===(string)$_GET['week']&&(string)$c['season']===(string)($_GET['season']??$c['season']))){$selected=$c;$index=$i;break;}
 if(!$selected){$fixtures=[];$label='Weekly recap';$progress=false;$previous=$next=null;
  if(isset($_GET['week'])){http_response_code(404);exit('Recap not found');}
 }else{
  $q=$db->prepare('SELECT f.id,f.status,f.home_score,f.away_score,f.kickoff_utc FROM fixtures f JOIN fixture_gameweeks g ON g.fixture_id=f.id WHERE g.season=? AND g.gameweek=?');
  $q->execute([$selected['season'],$selected['gameweek']]);$fixtures=$q->fetchAll(PDO::FETCH_ASSOC);
  $label='Gameweek '.$selected['gameweek'].' · '.$selected['season'].'/'.substr((string)($selected['season']+1),2);$progress=false;
  $url=fn($c)=>'/recap?period=week&amp;season='.(int)$c['season'].'&amp;week='.(int)$c['gameweek'];
  $previous=isset($choices[$index+1])?$url($choices[$index+1]):null;$next=$index>0?$url($choices[$index-1]):null;
 }
}
$done=[];$goals=0;
foreach($fixtures as $f){
 if(in_array($f['status'],['FT','AET','PEN'],true)&&$f['home_score']!==null&&$f['away_score']!==null&&strtotime($f['kickoff_utc'])<=time()){$done[]=(int)$f['id'];$goals+=(int)$f['home_score']+(int)$f['away_score'];}
 elseif(!in_array($f['status'],['PST','CANC','ABD'],true))$progress=true;
}
$s=recapData($db,$done);$ms=pcMarketStats($db,$done);$seasonCalled=pcMarketStats($db,pcSeasonFixtureIds($db))['called'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=re($label)?> recap | PredictionComp</title><meta name="robots" content="noindex,follow"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/player-nav.css?v=6"><link rel="stylesheet" href="/assets/theme.css?v=20261019"><style>
*{box-sizing:border-box}body{margin:0}main,body>header,footer{max-width:1050px;margin:auto;padding:24px}h1{font-size:clamp(30px,5vw,46px);line-height:1.15}.recapgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.recapcard{min-width:0;border:1px solid var(--line,#304655);border-radius:14px;background:var(--ink-1,#102330);padding:22px}.recapcard h2{font-size:23px;margin:0 0 14px}.recapcard p{line-height:1.65;overflow-wrap:anywhere}.recapstats{display:flex;flex-wrap:wrap;gap:14px;margin:24px 0}.recapstats div{flex:1;min-width:120px;padding:16px;border:1px solid var(--line,#304655);border-radius:10px}.recapstats b{display:block;font-size:28px}.recapstats span,.recapnote{font-size:14px;color:var(--text-2,#b4c7d2);line-height:1.65}.recapnav{display:flex;flex-wrap:wrap;gap:18px;margin:20px 0}.recapnav a{padding:10px 0}li{line-height:1.7;margin-bottom:10px}.recapwide{grid-column:1/-1;margin-bottom:18px}.recapstar{margin:0 0 18px;padding:22px;border-radius:14px;border:1px solid var(--gold-line,rgba(120,215,207,.45));background:var(--gold-soft,rgba(120,215,207,.12))}.recapstar h2{margin:6px 0;font-size:clamp(26px,4vw,36px)}.recapstar p{margin:0;color:var(--text-2,#b4c7d2)}.recapkicker{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--gold,#78d7cf);font-weight:700}.recaptablewrap{overflow-x:auto}.recaptable{width:100%;border-collapse:collapse;font-size:15px}.recaptable th,.recaptable td{padding:9px 8px;text-align:center;border-bottom:1px solid var(--line,#304655);white-space:nowrap}.recaptable th{font-size:13px;color:var(--text-2,#b4c7d2);font-weight:600}.recaptable .l{text-align:left}.recaptable tr.lead td{background:var(--gold-soft,rgba(120,215,207,.12))}.recaptable .up{color:var(--green,#46cf8f)}.recaptable .down{color:var(--red,#f0707e)}.honours{padding-left:0;list-style:none}.honours li{padding:10px 0;border-bottom:1px solid var(--line,#304655)}.honours li:last-child{border-bottom:0}.badge{display:inline-block;font-size:12px;font-weight:700;padding:2px 8px;margin-right:8px;border-radius:99px;background:var(--gold,#78d7cf);color:var(--gold-ink,#09252a);vertical-align:middle}@media(max-width:650px){.recaptable .m{display:none}.recaptable{font-size:14px}.recaptable th,.recaptable td{padding:8px 5px}}@media(max-width:650px){main,body>header,footer{padding:16px}.recapgrid{grid-template-columns:1fr}.recapcard{padding:18px}}
</style><link rel="stylesheet" href="/assets/mobile.css?v=1"></head><body><header class="siteheader"><?php siteHeaderNavigation();?></header><main><p><a href="/my-results">← My results</a></p><nav class="recapnav" aria-label="Recap period"><a href="/recap?period=week">Weekly recap</a><a href="/recap?period=month">Current month</a></nav><h1><?=re($label)?> recap</h1><p class="recapnote"><?=$progress?'So far — highlights update as matches finish.':'Finished matches — the highlights are in.'?> Weekly recaps follow official Premier League gameweeks; monthly recaps use UK kick-off dates.</p><nav class="recapnav" aria-label="Browse recaps"><?php if($previous):?><a href="<?=$previous?>">← Previous <?=$period==='week'?'gameweek':'month'?></a><?php endif;if($next):?><a href="<?=$next?>">Next <?=$period==='week'?'gameweek':'month'?> →</a><?php endif;?></nav>
<?php $pw=$period==='week'?'gameweek':'month';$acc=$s['picks']?round(100*$s['correct']/$s['picks']):0;?>
<div class="recapstats"><?php foreach([[count($done),'finished matches'],[count($s['players']),'real players'],[$s['exact'],'exact scores called'],[$acc.'%','results called right'],[$goals,'goals scored']] as [$value,$caption]):?><div><b><?=re($value)?></b><span><?=re($caption)?></span></div><?php endforeach;?></div>
<?php if(!$s['picks']):?><section class="recapcard"><h2>The story is still to come</h2><p>No eligible real-player predictions on finished matches in this period yet. Check back after the next results.</p></section><?php else:?>
<?php if($s['top']):?><section class="recapstar"><span class="recapkicker"><?=$progress?'Leading the '.$pw.' so far':'Player of the '.$pw?></span><h2><?=re(implode(' & ',array_column($s['top'],'name')))?></h2><p><?php if(count($s['top'])===1):$t=$s['top'][0];?><?=$t['points']?> points from <?=$t['picks']?> predictions · <?=$t['exact']?> exact score<?=$t['exact']===1?'':'s'?> · <?=$t['correct']?> correct result<?=$t['correct']===1?'':'s'?><?php else:?>Level on <?=$s['top'][0]['points']?> points<?php endif;?></p></section><?php endif;?>
<section class="recapcard recapwide"><h2><?=$pw==='gameweek'?'Gameweek':'Monthly'?> table</h2><div class="recaptablewrap"><table class="recaptable"><thead><tr><th>#</th><th class="l">Player</th><th>Pts</th><th>Exact</th><th>Results</th><th class="m">Played</th><th class="m">Pts/match</th><th title="Points per match above or below the SIM1 bots on the same matches">v SIM1</th></tr></thead><tbody><?php foreach($s['table'] as $p):?><tr<?=$p['rank']===1&&$p['points']>0?' class="lead"':''?>><td><?=$p['rank']?></td><td class="l"><?=re($p['name'])?></td><td><b><?=$p['points']?></b></td><td><?=$p['exact']?></td><td><?=$p['correct']?></td><td class="m"><?=$p['picks']?></td><td class="m"><?=number_format($p['points']/$p['picks'],2)?></td><td><?php if($p['simPicks']):$d=$p['simDiff']/$p['simPicks'];?><span class="<?=$d>0.005?'up':($d<-0.005?'down':'')?>"><?=($d>0.005?'+':'').number_format($d,2)?></span><?php else:?>–<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><p class="recapnote">5 points for an exact score, 3 for the right winner or draw. Ties on points are split by exact scores. “v SIM1” is points per match above or below the average SIM1 bot on the same matches.</p></section>
<section class="recapcard recapwide"><h2>Exact score honours</h2><?php if(!$s['exacts']):?><p>No exact scores yet<?=$progress?' — still time':''?>.</p><?php else:?><p class="recapnote">Every spot-on score this <?=$pw?>, rarest first.</p><ul class="honours"><?php foreach($s['exacts'] as $i=>$e):$r=$e['entries'][0];?><li><?php if($i===0||abs($e['share']-$s['exacts'][0]['share'])<1e-9):?><span class="badge">Rarest call</span><?php endif;?><strong><?=re(implode(', ',array_column($e['entries'],'display_name')))?></strong> called <?=rf($r)?><br><span class="recapnote"><?=count($e['entries'])===1?'Only 1':count($e['entries'])?> of <?=$e['total']?> player<?=$e['total']===1?'':'s'?> nailed it<?php if($e['cs']!==null):?> · exact score priced at <strong><?=number_format($e['cs'],1)?></strong><?php elseif($e['price']!==null):?> · result priced at <?=number_format($e['price'],2)?><?php endif;?></span></li><?php endforeach;?></ul><?php endif;?></section>
<div class="recapgrid">
<section class="recapcard"><h2>Boldest correct call</h2><p class="recapnote">The longest pre-match odds on a correct winner or draw.</p><?php if(!$s['best']):?><p>No winning calls with valid pre-match odds yet.</p><?php else:?><ul><?php foreach($s['best'] as $r):?><li><strong><?=re($r['display_name'])?></strong> · <?=number_format($r['price'],2)?> odds<br><?=rf($r)?> · predicted <?=re($r['home_score'].'–'.$r['away_score'])?><?=recapPoints($r)===5?' <span class="badge">Exact</span>':''?></li><?php endforeach;?></ul><?php endif;?></section>
<section class="recapcard"><h2>Sharpest scoring rate</h2><?php if(!$s['sharp']):?><p>Needs at least <?=$s['sharpMin']?> finished predictions and some points.</p><?php else:foreach($s['sharp'] as $p):?><p><strong><?=re($p['name'])?> · <?=number_format($p['points']/$p['picks'],2)?> points per match</strong><br><?=$p['points']?> points from <?=$p['picks']?> predictions</p><?php endforeach;endif;?><p class="recapnote">Minimum <?=$s['sharpMin']?> predictions, so players who entered fewer matches still get a fair comparison.</p></section>
<section class="recapcard"><h2>Humans v SIM1</h2><?php if(!$s['sim']):?><p>No SIM1 predictions on these matches yet.</p><?php else:$h=$s['sim']['human'];$bt=$s['sim']['bot'];?><p><strong><?=$h>$bt+0.005?'The humans won':($bt>$h+0.005?'The bots won':'All square')?></strong> · real players averaged <b><?=number_format($h,2)?></b> points per prediction against <b><?=number_format($bt,2)?></b> for SIM1 on the same matches.</p><?php if($s['sim']['beat']):?><p><?=count($s['sim']['beat'])?> of <?=$s['sim']['players']?> players beat SIM1: <strong><?=re(implode(', ',array_map(fn($p)=>$p['name'].' (+'.number_format($p['simDiff']/$p['simPicks'],2).')',array_slice($s['sim']['beat'],0,5))))?></strong>.</p><?php else:?><p>Nobody beat SIM1 this <?=$pw?>.</p><?php endif;?><?php endif;?><?php if($ms['matches']):?><p><strong>The Bookie</strong>, who always backs the bookmakers' favourite score, averaged <b><?=number_format($ms['bookie']['points']/$ms['matches'],2)?></b> on the <?=$ms['matches']?> match<?=$ms['matches']===1?'':'es'?> with correct-score prices.</p><?php endif;?><p class="recapnote">SIM1 is our expert grade of bot. Figures are points per match. <a href="/can-you-beat-sim1">Can you beat SIM1?</a></p></section>
<section class="recapcard"><h2>How everyone did</h2><p><strong><?=$s['correct']?> of <?=$s['picks']?> predictions</strong> got the winner or draw right (<?=$acc?>%). <?=$s['exact']?> exact score<?=$s['exact']===1?'':'s'?> earned five points; <?=$s['correct']-$s['exact']?> other correct results earned three.</p><?php if($s['crowd']['called']):?><p><strong>Wisdom of the crowd:</strong> the most popular result among real players was right in <?=$s['crowd']['right']?> of <?=$s['crowd']['called']?> matches.</p><?php endif;?></section>
<?php if($ms['called']||$seasonCalled):?><section class="recapcard"><h2>Called it</h2><p class="recapnote">The longest-priced exact score: bookmaker correct-score prices before kick-off, margin removed.</p><?php if($ms['called']):$c=$ms['called'][0];?><p><span class="badge">Called it</span><strong><?=re($c['name'])?></strong> called <?=rf(['id'=>$c['fixture']['id'],'home'=>$c['fixture']['home'],'away'=>$c['fixture']['away'],'actual_home'=>$c['fixture']['home_score'],'actual_away'=>$c['fixture']['away_score']])?><br>a <strong><?=pcOneIn($c['prob'])?></strong> shot (priced at <?=number_format($c['price'],1)?>)</p><?php foreach(array_slice($ms['called'],1,3) as $c):?><p class="recapnote"><?=re($c['name'])?> · <?=re($c['fixture']['home'].' '.$c['fixture']['home_score'].'–'.$c['fixture']['away_score'].' '.$c['fixture']['away'])?> · <?=pcOneIn($c['prob'])?></p><?php endforeach;else:?><p>No priced exact scores this <?=$pw?>.</p><?php endif;?><?php if($seasonCalled):$c=$seasonCalled[0];?><p class="recapnote"><strong>Season record:</strong> <?=re($c['name'])?>, <?=re($c['fixture']['home'].' '.$c['fixture']['home_score'].'–'.$c['fixture']['away_score'].' '.$c['fixture']['away'])?>, <?=pcOneIn($c['prob'])?>.</p><?php endif;?></section><?php endif;?>
<?php if($ms['players']):$lp=array_values($ms['players']);usort($lp,fn($a,$b)=>$b['luck']<=>$a['luck']);?><section class="recapcard"><h2>Luck v skill</h2><p class="recapnote">Expected points are what each pick was worth on average before kick-off, from the correct-score prices. Above expected = luck on your side; a high expected rate = smart picks.</p><div class="recaptablewrap"><table class="recaptable"><thead><tr><th class="l">Player</th><th>Exp/match</th><th>Pts/match</th><th>Luck</th></tr></thead><tbody><?php foreach($lp as $p):?><tr><td class="l"><?=re($p['name'])?></td><td><?=number_format($p['expected']/$p['n'],2)?></td><td><?=number_format($p['points']/$p['n'],2)?></td><td><span class="<?=$p['luck']>0.05?'up':($p['luck']<-0.05?'down':'')?>"><?=($p['luck']>0.05?'+':'').number_format($p['luck'],1)?></span></td></tr><?php endforeach;?></tbody></table></div><p class="recapnote">Only matches with stored correct-score prices count (<?=$ms['matches']?> this <?=$pw?>).</p></section><?php endif;?>
<section class="recapcard recapwide"><h2>The toughest result to call</h2><?php if(!$s['hard']):?><p>Needs at least three real-player predictions on a match.</p><?php else:$show=array_slice($s['hard'],0,3);foreach($show as $m):?><p><?=rf($m['fixture'])?><br><?php if($m['correct']===0):?>All <strong><?=$m['picks']?></strong> players who predicted it got the result wrong.<?php else:?>Only <strong><?=$m['correct']?> of <?=$m['picks']?></strong> players got the result right.<?php endif;?></p><?php endforeach;if(count($s['hard'])>3):?><p class="recapnote">…and <?=count($s['hard'])-3?> more match<?=count($s['hard'])-3===1?'':'es'?> just as tough.</p><?php endif;endif;?></section>
</div><?php endif;?>
<p class="recapnote">Real players only: SIM bots are excluded, and new guests appear once they qualify for the global table. Finished matches only; predictions for upcoming matches are never revealed. Odds are bookmaker prices stored before kick-off (result prices, plus correct-score prices from November 2026), so coverage can be incomplete.</p><p><a href="/#predict">Make your next predictions →</a></p></main><footer><a href="/my-results">My results</a> · <a href="/">PredictionComp</a></footer><?php playerNavigation();?></body></html>
